struct Provider(Mutex<BTreeMap<PathBuf,dm_preprocess::AcquiredSource>>);
impl dm_preprocess::SourceProvider for Provider{fn initial_environment(&self)->dm_preprocess::InitialEnvironment{dm_preprocess::InitialEnvironment::OriginalChecker0290}fn read(&self,_:&Path)->Result<String,String>{Err("actual Original acquisition required".into())}fn acquired_source(&self,path:&Path)->Result<Option<dm_preprocess::AcquiredSource>,String>{let mut rows=self.0.lock().unwrap();if let Some(value)=rows.get(path){return Ok(Some(value.clone()))}let bytes=std::fs::read(path).map_err(|e|e.to_string())?;let value=dm_preprocess::AcquiredSource::from_original_bytes(bytes,());rows.insert(path.to_path_buf(),value.clone());Ok(Some(value))}fn source_acquisition(&self,path:&Path,text:&dm_preprocess::SourceText)->Option<dm_preprocess::AcquiredSource>{self.0.lock().unwrap().get(path).filter(|value|value.lease().source_text().same_view(text)).cloned()}}
fn input(root:&Path)->(dm_analysis::policy_inputs::PolicyInputs,Arc<original_host::Host>){let seed=dm_tree::checker_builtins::original_analysis_seed().unwrap();let executor=dm_exec::BuildExecutor::new(1).unwrap();let host=original_host::Host::new();let settings=host.clone()as Arc<dyn SettingExpressionQueries>;let front=dm_tree::frontend::build_for_original_analysis_with_state_checked(&root.join("deepquarry.dme"),&Provider(Mutex::new(BTreeMap::new())),&Default::default(),dm_tree::frontend::FrontendConfig{workers:1,engine:Some(seed.frontend_seed()),observer:None},None,&executor,None,&settings).unwrap().with_body_queries(host.clone()as Arc<dyn BodySyntaxQueries>).unwrap();let view=front.source_view().unwrap();assert!(view.original_analysis_completeness().is_some());let raw=view.files().iter().filter(|file|file.captured).map(|file|dm_analysis::policy_inputs::HostCapture::analyze_raw(file.path.clone(),dm_analysis::policy_inputs::PolicyRole::DmSource,file.text.clone())).collect::<Vec<_>>();(dm_analysis::policy_inputs::PolicyInputs::capture_diagnostic(&view,raw).unwrap(),host)}
